import{_ as r,o as n,c as s,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Kursarten in Basisreports für SchILD-NRW 2","description":"","frontmatter":{"title":"Kursarten in Basisreports für SchILD-NRW 2","source_pageid":1657,"source_revision":7234},"headers":[],"relativePath":"hilfe/fruehere-verfahren/kursarten-basisreports-schild2.md","filePath":"hilfe/fruehere-verfahren/kursarten-basisreports-schild2.md"}'),i={name:"hilfe/fruehere-verfahren/kursarten-basisreports-schild2.md"};function t(h,e,u,d,l,o){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="kursarten-in-basisreports-fur-schild-nrw-2" tabindex="-1">Kursarten in Basisreports für SchILD-NRW 2 <a class="header-anchor" href="#kursarten-in-basisreports-fur-schild-nrw-2" aria-label="Permalink to &quot;Kursarten in Basisreports für SchILD-NRW 2&quot;">​</a></h1><p>Dieser Artikel beschreibt eine Einschränkung der <strong>Basisreportsammlung für SchILD-NRW 2</strong>. Für die aktuelle Sammlung verwenden Sie <a href="/reporting/basisreports/basisreportsammlung-leistungsuebersichten-halbjahr.html">Leistungsübersichten für ein Halbjahr</a>.</p><h2 id="bedeutung-des-parameters" tabindex="-1">Bedeutung des Parameters <a class="header-anchor" href="#bedeutung-des-parameters" aria-label="Permalink to &quot;Bedeutung des Parameters&quot;">​</a></h2><p>Der Parameter <code>UeberspringeFaecherMitDiesenKursarten</code> steuert, welche allgemeinen Kursarten nicht in der Fächertabelle, sondern gesondert darunter ausgegeben werden. Die im Wiki genannte Standardeinstellung ist <code>AGGT,ZUV</code>; mehrere Kursarten werden durch Kommas ohne Leerzeichen getrennt.</p><h2 id="einschrankung-in-schild-nrw-2" tabindex="-1">Einschränkung in SchILD-NRW 2 <a class="header-anchor" href="#einschrankung-in-schild-nrw-2" aria-label="Permalink to &quot;Einschränkung in SchILD-NRW 2&quot;">​</a></h2><p>Der frühere Wiki-Hinweis empfiehlt, diesen Parameter bei Verwendung der Basisreportsammlung für <strong>SchILD-NRW 2 leer zu lassen</strong>. Der damalige Reportdesigner hatte Probleme bei der Darstellung, wenn Kurse übersprungen wurden.</p><p>Als Alternative wurde die Fächertabelle so sortiert, dass die betreffenden Kurse am Ende standen. Dadurch mussten keine ausgeblendeten Fächer übersprungen werden. Anschließend mussten die Fächer auch in den Leistungsdaten der Schülerinnen und Schüler neu sortiert werden.</p><p>Diese Einschränkung bezieht sich auf die frühere Sammlung und den Reportdesigner von SchILD-NRW 2; sie ist keine allgemeine Vorgabe für die aktuelle Basisreportsammlung.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Basisreportsammlung:_Leistungs%C3%BCbersichten_Halbjahr" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7234.</p>',10)])])}const g=r(i,[["render",t]]);export{p as __pageData,g as default};
